// Gated DeltaNet prefill, raw CUDA, no external library.
//
//   q,k : [B,T,Hq,K] bf16      v : [B,T,Hv,V] bf16
//   g   : [B,T,Hv]   fp32      beta : [B,T,Hv] bf16
//   s0  : [B,Hv,K,V] fp32
//
// Per head the state S (K x V, fp32) obeys, with k"'^/q''^ the L2-normalized rows:
//   pred = k''^ . (d*S) ; res = beta*(v - pred) ; S = d*S + k''^ (x) res ; out = q''^ . S
//
// The V axis is independent, so it is tiled across thread blocks ("slabs").
// A warp holds one slab: lane = column (8) x row-group (4), 32 rows per lane.
// K-axis sums are warp shuffles over the four row groups; no smem barrier is
// needed for them. k/q rows are staged through smem in fp32 (one bf16->fp32
// conversion per value per warp instead of one per use).
//
// The scalar decay is folded away from the state: the block keeps S~ = S/D with
// D the running product of exp(g) since the last renormalization, so the state
// is rescaled every ~20 tokens instead of multiplied on every token.

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>

namespace {

constexpr int kTokens = 4096;
constexpr int kHeadsQ = 16;
constexpr int kHeadsV = 32;
constexpr int kKeyDim = 128;
constexpr int kValDim = 128;
constexpr int kSlabCols = 8;
constexpr int kSlabs = kValDim / kSlabCols;
constexpr int kRowsLane = 32;
constexpr int kGroups = 4;
constexpr int kSmemStride = kRowsLane + 8;  // pad: row groups start on distinct banks
constexpr float kL2Eps = 1e-6f;
constexpr float kQScale = 0.08838834764831845f;  // 128''^-0.5
constexpr float kRenorm = 1.0f / 1048576.0f;     // rescale the state below 2''^-20

struct alignas(8) Bf16x4 {
  __nv_bfloat162 lo;
  __nv_bfloat162 hi;
};

// per (token, value-head) scalars: decay, k 1/norm, q 1/norm*sqrt(K)''^-1, rate
struct alignas(16) TokenScale {
  float decay;
  float knorm;
  float qnorm;
  float rate;
};

__device__ __forceinline__ float4 bf16x4_to_f4(const Bf16x4& w) {
  float4 f;
  f.x = __bfloat162float(w.lo.x);
  f.y = __bfloat162float(w.lo.y);
  f.z = __bfloat162float(w.hi.x);
  f.w = __bfloat162float(w.hi.y);
  return f;
}

// One warp per token: L2 norms of the q/k rows plus the per-head decay/rate.
__global__ void gdn_prep(const __nv_bfloat16* __restrict__ q,
                         const __nv_bfloat16* __restrict__ k,
                         const float* __restrict__ g,
                         const __nv_bfloat16* __restrict__ beta,
                         TokenScale* __restrict__ scales) {
  const int lane = threadIdx.x & 31;
  const int warp = threadIdx.x >> 5;
  const int token = [REDACTED_SECRET] * 4 + warp;
  const int head = blockIdx.y;
  const size_t row = ((size_t)token * kHeadsQ + head) * kKeyDim;

  float4 kf = bf16x4_to_f4(*reinterpret_cast<const Bf16x4*>(k + row + 4 * lane));
  float4 qf = bf16x4_to_f4(*reinterpret_cast<const Bf16x4*>(q + row + 4 * lane));
  float ks = kf.x * kf.x + kf.y * kf.y + kf.z * kf.z + kf.w * kf.w;
  float qs = qf.x * qf.x + qf.y * qf.y + qf.z * qf.z + qf.w * qf.w;
#pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    ks += __shfl_xor_sync(0xffffffffu, ks, off);
    qs += __shfl_xor_sync(0xffffffffu, qs, off);
  }

  if (lane < 2) {
    const int hv = 2 * head + lane;
    TokenScale s;
    s.decay = __expf(g[(size_t)token * kHeadsV + hv]);
    s.knorm = rsqrtf(ks + kL2Eps);
    s.qnorm = rsqrtf(qs + kL2Eps) * kQScale;
    s.rate = __bfloat162float(beta[(size_t)token * kHeadsV + hv]);
    scales[(size_t)token * kHeadsV + hv] = s;
  }
}

// One warp per (value head, 8-column slab); loops the whole token axis.
__global__ __launch_bounds__(32) void gdn_scan(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    const TokenScale* __restrict__ scales,
    const float* __restrict__ state0,
    __nv_bfloat16* __restrict__ out,
    float* __restrict__ stateN) {
  const int lane = threadIdx.x;
  const int hv = blockIdx.y;
  const int hq = hv >> 1;
  const int colInGroup = lane & 7;
  const int group = lane >> 3;
  const int col = blockIdx.x * kSlabCols + colInGroup;
  const int rowBase = group * kRowsLane;

  __shared__ float kbuf[2][kGroups * kSmemStride];
  __shared__ float qbuf[2][kGroups * kSmemStride];

  const size_t colOff = (size_t)hv * kKeyDim * kValDim + (size_t)rowBase * kValDim + col;
  float state[kRowsLane];
#pragma unroll
  for (int j = 0; j < kRowsLane; ++j) state[j] = state0[colOff + (size_t)j * kValDim];

  // lane l carries k/q row values [4l, 4l+4); row group = l>>3, slot = l&7
  const int slot = group * kSmemStride + 4 * colInGroup;

  auto stage = [&](int token, int buf) {
    const size_t row = ((size_t)token * kHeadsQ + hq) * kKeyDim + 4 * lane;
    *reinterpret_cast<float4*>(&kbuf[buf][slot]) =
        bf16x4_to_f4(*reinterpret_cast<const Bf16x4*>(k + row));
    *reinterpret_cast<float4*>(&qbuf[buf][slot]) =
        bf16x4_to_f4(*reinterpret_cast<const Bf16x4*>(q + row));
  };

  stage(0, 0);
  __syncwarp();

  float acc = 0.0f;  // running decay product since the last state rescale

  for (int t = 0; t < kTokens; ++t) {
    const int cur = t & 1;
    const int next = cur ''^ 1;

    // prefetch: the global loads retire while token t is computed
    const int fetch = (t + 1 < kTokens) ? t + 1 : t;
    const size_t fetchRow = ((size_t)fetch * kHeadsQ + hq) * kKeyDim + 4 * lane;
    Bf16x4 wk = *reinterpret_cast<const Bf16x4*>(k + fetchRow);
    Bf16x4 wq = *reinterpret_cast<const Bf16x4*>(q + fetchRow);

    const TokenScale sc = scales[(size_t)t * kHeadsV + hv];

    float kk[kRowsLane];
#pragma unroll
    for (int i = 0; i < kGroups; ++i)
      *reinterpret_cast<float4*>(&kk[4 * i]) =
          *reinterpret_cast<const float4*>(&kbuf[cur][slot + i * 4 - 4 * colInGroup + 4 * i - 4 * i]);

    float a0 = 0.0f, a1 = 0.0f, a2 = 0.0f, a3 = 0.0f;
#pragma unroll
    for (int j = 0; j < kRowsLane; j += 4) {
      a0 = fmaf(kk[j + 0], state[j + 0], a0);
      a1 = fmaf(kk[j + 1], state[j + 1], a1);
      a2 = fmaf(kk[j + 2], state[j + 2], a2);
      a3 = fmaf(kk[j + 3], state[j + 3], a3);
    }
    float pred = (a0 + a1) + (a2 + a3);
    pred += __shfl_xor_sync(0xffffffffu, pred, 8);
    pred += __shfl_xor_sync(0xffffffffu, pred, 16);

    const float decay = sc.decay;
    acc *= decay;                                  // acc = product of decays so far
    const float vv = __bfloat162float(v[((size_t)t * kHeadsV + hv) * kValDim + col]);
    const float res = sc.rate * (vv - (sc.knorm * acc) * pred);
    const float step = res * sc.knorm / acc;       // residual in rescaled units

#pragma unroll
    for (int j = 0; j < kRowsLane; ++j) state[j] = fmaf(kk[j], step, state[j]);

    float qq[kRowsLane];
#pragma unroll
    for (int i = 0; i < kGroups; ++i)
      *reinterpret_cast<float4*>(&qq[4 * i]) =
          *reinterpret_cast<const float4*>(&qbuf[cur][slot + 4 * i - 4 * colInGroup + 4 * i - 4 * i]);

    float b0 = 0.0f, b1 = 0.0f, b2 = 0.0f, b3 = 0.0f;
#pragma unroll
    for (int j = 0; j < kRowsLane; j += 4) {
      b0 = fmaf(qq[j + 0], state[j + 0], b0);
      b1 = fmaf(qq[j + 1], state[j + 1], b1);
      b2 = fmaf(qq[j + 2], state[j + 2], b2);
      b3 = fmaf(qq[j + 3], state[j + 3], b3);
    }
    float value = (b0 + b1) + (b2 + b3);
    value += __shfl_xor_sync(0xffffffffu, value, 8);
    value += __shfl_xor_sync(0xffffffffu, value, 16);
    out[((size_t)t * kHeadsV + hv) * kValDim + col] =
        __float2bfloat16(sc.qnorm * acc * value);

    if (acc < kRenorm) {  // keep 1/acc inside fp32 range
#pragma unroll
      for (int j = 0; j < kRowsLane; ++j) state[j] *= acc;
      acc = 1.0f;
    }

    *reinterpret_cast<float4*>(&kbuf[next][slot]) = bf16x4_to_f4(wk);
    *reinterpret_cast<float4*>(&qbuf[next][slot]) = bf16x4_to_f4(wq);
    __syncwarp();
  }

#pragma unroll
  for (int j = 0; j < kRowsLane; ++j)
    stateN[colOff + (size_t)j * kValDim] = state[j] * acc;
}

void check(const torch::Tensor& tensor, const char* name, int64_t last, c10::ScalarType dtype) {
  TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
  TORCH_CHECK(tensor.scalar_type() == dtype, name, " dtype mismatch");
  TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
            const torch::Tensor& g, const torch::Tensor& beta,
            const torch::Tensor& initial_state, torch::Tensor& output,
            torch::Tensor& final_state) {
  check(q, "q", kKeyDim, at::kBFloat16);
  check(k, "k", kKeyDim, at::kBFloat16);
  check(v, "v", kValDim, at::kBFloat16);
  check(g, "g", kHeadsV, at::kFloat);
  check(beta, "beta", kHeadsV, at::kBFloat16);
  check(initial_state, "initial_state", kValDim, at::kFloat);
  TORCH_CHECK(q.size(0) == 1 && k.size(0) == 1 && v.size(0) == 1, "batch must be 1");
  TORCH_CHECK(q.size(1) == kTokens && q.size(2) == kHeadsQ && q.size(3) == kKeyDim,
              "unexpected q shape");
  TORCH_CHECK(v.size(1) == kTokens && v.size(2) == kHeadsV && v.size(3) == kValDim,
              "unexpected v shape");
  TORCH_CHECK(output.scalar_type() == at::kBFloat16 && output.is_contiguous() &&
                  output.numel() == (int64_t)kTokens * kHeadsV * kValDim,
              "unexpected output");
  TORCH_CHECK(final_state.scalar_type() == at::kFloat && final_state.is_contiguous() &&
                  final_state.numel() == (int64_t)kHeadsV * kKeyDim * kValDim,
              "unexpected final_state");

  const c10::cuda::CUDAGuard guard(q.device());
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();

  static TokenScale* scales = nullptr;
  if (scales == nullptr) {
    cudaMalloc(&scales, sizeof(TokenScale) * (size_t)kTokens * kHeadsV);
  }

  gdn_prep<<<dim3(kTokens / 4, kHeadsQ), 128, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(k.data_ptr<at::BFloat16>()),
      g.data_ptr<float>(),
      reinterpret_cast<const __nv_bfloat16*>(beta.data_ptr<at::BFloat16>()), scales);
  C10_CUDA_KERNEL_LAUNCH_CHECK();

  gdn_scan<<<dim3(kSlabs, kHeadsV), 32, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(k.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(v.data_ptr<at::BFloat16>()), scales,
      initial_state.data_ptr<float>(),
      reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
      final_state.data_ptr<float>());
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &kernel);
}
EOF
