    float pred = (a0 + a1) + (a2 + a3);
    pred += __shfl_xor_sync(0xffffffffu, pred, 8);
    pred += __shfl_xor_sync(0xffffffffu, pred, 16);

    const float decay = sc.decay;
    acc *= decay;                                  // acc = product of decays so far
    const float vv = __bfloat162float(v[((size_t)t * kHeadsV + hv) * kValDim + col]);
    const float res = sc.rate * (vv - (sc.knorm * acc) * pred);
    const float step = res * sc.knorm / acc;       // residual in rescaled units

#pragma unroll
    for (int j = 0; j < kRowsLane; ++j) state[j] = fmaf(kk[j], step, state[j]);

    float qq[kRowsLane];
#pragma unroll
    for (int i = 0; i < kGroups; ++i)
      *reinterpret_cast<float4*>(&qq[4 * i]) =
          *reinterpret_cast<const float4*>(&qbuf[cur][slot + 4 * i - 4 * colInGroup + 4 * i - 4 * i]);

    float b0 = 0.0f, b1 = 0.0f, b2 = 0.0f, b3 = 0.0f;
#pragma unroll
    for (int j = 0; j < kRowsLane; j += 4) {
      b0 = fmaf(qq[j + 0], state[j + 0], b0);
      b1 = fmaf(qq[j + 1], state[j + 1], b1);
      b2 = fmaf(qq[j + 2], state[j + 2], b2);
      b3 = fmaf(qq[j + 3], state[j + 3], b3);
    }
    float value = (b0 + b1) + (b2 + b3);
    value += __shfl_xor_sync(0xffffffffu, value, 8);
    value += __shfl_xor_sync(0xffffffffu, value, 16);
    out[((size_t)t * kHeadsV + hv) * kValDim + col] =
        __float2bfloat16(sc.qnorm * acc * value);

    if (acc < kRenorm) {  // keep 1/acc inside fp32 range
#pragma unroll
      for (int j = 0; j < kRowsLane; ++j) state[j] *= acc;
      acc = 1.0f;
    }

    *reinterpret_cast<float4*>(&kbuf[next][slot]) = bf16x4_to_f4(wk);
    *reinterpret_cast<float4*>(&qbuf[next][slot]) = bf16x4_to_f4(wq);
    __syncwarp();
  }

#pragma unroll
  for (int j = 0; j < kRowsLane; ++j)
    stateN[colOff + (size_t)j * kValDim] = state[j] * acc;
}

void check(const torch::Tensor& tensor, const char* name, int64_t last, c10::ScalarType dtype) {
  TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
  TORCH_CHECK(tensor.scalar_type() == dtype, name, " dtype mismatch");
  TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
            const torch::Tensor& g, const torch::Tensor& beta,
            const torch::Tensor& initial_state, torch::Tensor& output,
            torch::Tensor& final_state) {
  check(q, "q", kKeyDim, at::kBFloat16);
  check(k, "k", kKeyDim, at::kBFloat16);
  check(v, "v", kValDim, at::kBFloat16);
  check(g, "g", kHeadsV, at::kFloat);
  check(beta, "beta", kHeadsV, at::kBFloat16);
  check(initial_state, "initial_state", kValDim, at::kFloat);
  TORCH_CHECK(q.size(0) == 1 && k.size(0) == 1 && v.size(0) == 1, "batch must be 1");
  TORCH_CHECK(q.size(1) == kTokens && q.size(2) == kHeadsQ && q.size(3) == kKeyDim,
              "unexpected q shape");
  TORCH_CHECK(v.size(1) == kTokens && v.size(2) == kHeadsV && v.size(3) == kValDim,
              "unexpected v shape");
  TORCH_CHECK(output.scalar_type() == at::kBFloat16 && output.is_contiguous() &&
                  output.numel() == (int64_t)kTokens * kHeadsV * kValDim,
              "unexpected output");
  TORCH_CHECK(final_state.scalar_type() == at::kFloat && final_state.is_contiguous() &&
                  final_state.numel() == (int64_t)kHeadsV * kKeyDim * kValDim,
              "unexpected final_state");

  const c10::cuda::CUDAGuard guard(q.device());
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();

  static TokenScale* scales = nullptr;
  if (scales == nullptr) {
    cudaMalloc(&scales, sizeof(TokenScale) * (size_t)kTokens * kHeadsV);
  }

  gdn_prep<<<dim3(kTokens / 4, kHeadsQ), 128, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(k.data_ptr<at::BFloat16>()),
      g.data_ptr<float>(),
      reinterpret_cast<const __nv_bfloat16*>(beta.data_ptr<at::BFloat16>()), scales);
  C10_CUDA_KERNEL_LAUNCH_CHECK();

  gdn_scan<<<dim3(kSlabs, kHeadsV), 32, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(k.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(v.data_ptr<at::BFloat16>()), scales,
      initial_state.data_ptr<float>(),
      reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
      final_state.data_ptr<float>());
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &kernel);
}
