import torch

L2_EPS = 1e-6


def run(q, k, v, g, beta, initial_state):
    """Scalar-gated delta recurrence; state axes are key, value."""
    key_dim = q.shape[-1]
    repeats = v.shape[2] // q.shape[2]

    # Normalize in FP32 before expanding grouped heads.
    q32, k32 = q.float(), k.float()
    q32 = q32 * torch.rsqrt(q32.square().sum(-1, keepdim=True) + L2_EPS)
    k32 = k32 * torch.rsqrt(k32.square().sum(-1, keepdim=True) + L2_EPS)
    q32 = (q32 * key_dim**-0.5).repeat_interleave(repeats, dim=2)
    k32 = k32.repeat_interleave(repeats, dim=2)
    values, rates, decay = v.float(), beta.float(), g.float().exp()
    state = initial_state.float().clone()
    output = torch.empty_like(v)

    # Decay precedes the prediction; reads use the updated state.
    for token in range(q.shape[1]):
        keys = k32[:, token].unsqueeze(-1)
        prior = state * decay[:, token, :, None, None]
        prediction = (prior * keys).sum(dim=-2)
        residual = rates[:, token, :, None] * (values[:, token] - prediction)
        state = prior + keys * residual.unsqueeze(-2)
        output[:, token] = (state * q32[:, token].unsqueeze(-1)).sum(dim=-2)

    return output, state.contiguous()
