// One warp per (value head, 4 column slab); loops the whole token axis.
__global__ __launch_bounds__(kWarp) void gdn_scan(
    const float* __restrict__ kh, const float* __restrict__ qh,
    const __nv_bfloat16* __restrict__ v, const TokenScale* __restrict__ scales,
    const float* __restrict__ state0, __nv_bfloat16* __restrict__ out,
    float* __restrict__ stateN) {
  const int lane = threadIdx.x;
  const int hv = blockIdx.y;
  const int hq = hv >> 1;
  const int col = blockIdx.x * kSlabCols + lane % kSlabCols;
  const int rowBase = (lane / kSlabCols) * kRowsLane;

  const size_t colOff = (size_t)hv * (kKeyDim * kValDim) + (size_t)rowBase * kValDim + col;
  float S[kRowsLane];
#pragma unroll
  for (int i = 0; i < kRowsLane; ++i) S[i] = state0[colOff + (size_t)i * kValDim];

  const float* kp = kh + (size_t)hq * (kTokens + kPad) * kKeyDim + rowBase;
  const float* qp = qh + (size_t)hq * (kTokens + kPad) * kKeyDim + rowBase;
  const TokenScale* sp = scales + hv;
  const __nv_bfloat16* vp = v + (size_t)hv * kValDim + col;
  __nv_bfloat16* op = out + (size_t)hv * kValDim + col;
  constexpr int kRowStride = kKeyDim;
  constexpr int kScaleStride = kHeadsV;
  constexpr int kOutStride = kHeadsV * kValDim;

  const char* vrow = reinterpret_cast<const char*>(v + (size_t)hv * kValDim);
  const char* srow = reinterpret_cast<const char*>(scales + hv);

  Row a, b;
  load_row(a, kp, qp, sp, vp);
  float decay = 1.0f, rdecay = 1.0f;

  int t = 0;
  for (; t + 2 < kTokens; t += 2) {
    scan_step(a, b, kp + (t + 1) * kRowStride, qp + (t + 1) * kRowStride,
              sp + (t + 1) * kScaleStride, vp + (t + 1) * kOutStride, S, decay, rdecay,
              op + t * kOutStride);
    warm_row(kp + (t + kLookahead) * kRowStride, qp + (t + kLookahead) * kRowStride,
             vrow + (size_t)(t + kLookahead) * kVStride,
             srow + (size_t)(t + kLookahead) * kScaleBytes, lane);
    scan_step(b, a, kp + (t + 2) * kRowStride, qp + (t + 2) * kRowStride,
              sp + (t + 2) * kScaleStride, vp + (t + 2) * kOutStride, S, decay, rdecay,
              op + (t + 1) * kOutStride);
    warm_row(kp + (t + 1 + kLookahead) * kRowStride,
             qp + (t + 1 + kLookahead) * kRowStride,
             vrow + (size_t)(t + 1 + kLookahead) * kVStride,
             srow + (size_t)(t + 1 + kLookahead) * kScaleBytes, lane);
  }

  for (; t < kTokens; ++t) {
    const int fetch = (t + 1 < kTokens) ? t + 1 : t;
    const Row& cur = (t & 1) ? b : a;
    Row& nxt = (t & 1) ? a : b;
    scan_step(cur, nxt, kp + fetch * kRowStride, qp + fetch * kRowStride,
              sp + fetch * kScaleStride, vp + fetch * kOutStride, S, decay, rdecay,
              op + t * kOutStride);
  }

#pragma unroll
  for (int i = 0; i < kRowsLane; ++i)
    stateN[colOff + (size_t)i * kValDim] = S[i] * decay;
}

void check(const torch::Tensor& t, const char* name, c10::ScalarType dtype) {
  TORCH_CHECK(t.is_cuda(), name, " must be a CUDA tensor");
  TORCH_CHECK(t.scalar_type() == dtype, name, " dtype mismatch");
  TORCH_CHECK(t.is_contiguous(), name, " must be contiguous");
}

